import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';
import { backendApi } from '../api/backend';
import CarGrid from '../components/CarGrid';
import { LoadingState, ErrorState } from '../components/admin/AdminStates';

export default function Home() {
  const [cars, setCars] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

  useEffect(() => {
    backendApi.getCars()
      .then((data) => setCars((data || []).slice(0, 3)))
      .catch((err) => setError(err.message))
      .finally(() => setLoading(false));
  }, []);

  return (
    <div className="space-y-10">
      <section className="bg-blue-600 text-white rounded-2xl p-10 text-center space-y-4">
        <h1 className="text-3xl md:text-4xl font-bold">บริการเช่ารถออนไลน์ สะดวก รวดเร็ว</h1>
        <p className="text-blue-100 max-w-xl mx-auto">
          เลือกรถที่ถูกใจ เช็กสถานะว่างแบบเรียลไทม์ จองออนไลน์ได้ทันทีตลอด 24 ชั่วโมง
        </p>
        <Link to="/cars" className="inline-block bg-white text-blue-600 font-semibold px-6 py-3 rounded-lg shadow hover:bg-gray-100">
          ดูรถทั้งหมดเลย
        </Link>
      </section>

      <section>
        <div className="flex justify-between items-center mb-6">
          <h2 className="text-2xl font-bold">รถแนะนำสำหรับคุณ</h2>
          <Link to="/cars" className="text-blue-600 hover:underline text-sm">ดูทั้งหมด &rarr;</Link>
        </div>
        {loading && <LoadingState />}
        {error && <ErrorState message={error} />}
        {!loading && !error && <CarGrid cars={cars} />}
      </section>
    </div>
  );
}
